// src/App.tsx
import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import RecruitmentPage from './pages/Recruitment';

// Placeholder for other pages
const StaffPage = () => <Layout><div className="p-8"><h1>Staff Management</h1><p className="text-gray-500">Classified information coming soon...</p></div></Layout>;
const MissionsPage = () => <Layout><div className="p-8"><h1>Operations</h1><p className="text-gray-500">Secure line establishing...</p></div></Layout>;
const MarketPage = () => <Layout><div className="p-8"><h1>Scouting & Market</h1><p className="text-gray-500">Connecting to the deep web...</p></div></Layout>;

const App: React.FC = () => {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Navigate to="/dashboard" replace />} />
        <Route path="/dashboard" element={<Layout><Dashboard /></Layout>} />
        <Route path="/staff" element={<StaffPage />} />
        <Route path="/missions" element={<MissionsPage />} />
        <Route path="/market" element={<RecruitmentPage />} />
      </Routes>
    </Router>
  );
};

export default App;
